<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { actualizarHorario, cambiarEstadoHorario, crearHorario, listarHorarios } from '../services/horarios'
import type { HorarioPayload, HorarioTrabajo, RegimenHorario } from '../interfaces/horario.interface'

const rows=ref<HorarioTrabajo[]>([]),regimenes=ref<RegimenHorario[]>([]),criterio=ref(''),regimenId=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const blank=():HorarioPayload=>({regimen_id:0,codigo:'',descripcion:'',entrada_1:'',salida_1:'',entrada_2:null,salida_2:null}),form=reactive<HorarioPayload>(blank())
const duration=computed(()=>{const minutes=(a:string|null,b:string|null)=>{if(!a||!b)return 0;const start=a.split(':').map(Number),end=b.split(':').map(Number);return Math.max(0,(end[0]??0)*60+(end[1]??0)-(start[0]??0)*60-(start[1]??0))};const value=minutes(form.entrada_1,form.salida_1)+minutes(form.entrada_2,form.salida_2);return value?`${Math.floor(value/60)}h ${value%60?`${value%60}min`:''}`:'—'})
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.',time=(v:string|null)=>v?v.slice(0,5):'—'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarHorarios(criterio.value,regimenId.value,next);rows.value=r.data;regimenes.value=r.regimenes;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:HorarioTrabajo){editing.value=item?.id??null;Object.assign(form,item?{regimen_id:item.regimen_id,codigo:item.codigo,descripcion:item.descripcion,entrada_1:time(item.entrada_1),salida_1:time(item.salida_1),entrada_2:item.entrada_2?time(item.entrada_2):null,salida_2:item.salida_2?time(item.salida_2):null}:blank());modal.value=true;error.value=''}
async function save(){if(!form.regimen_id||!form.codigo.trim()||!form.descripcion.trim()||!form.entrada_1||!form.salida_1)return void(error.value='Complete todos los campos obligatorios.');if(Boolean(form.entrada_2)!==Boolean(form.salida_2))return void(error.value='Complete ambos horarios del segundo bloque o déjelos vacíos.');saving.value=true;try{const payload={...form,codigo:form.codigo.trim().toUpperCase(),descripcion:form.descripcion.trim().toUpperCase()};editing.value?await actualizarHorario(editing.value,payload):await crearHorario(payload);success.value=`Horario ${editing.value?'actualizado':'registrado'} correctamente.`;modal.value=false;await load(page.value)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:HorarioTrabajo){if(!confirm(`¿Desea ${item.estado?'desactivar':'activar'} el horario ${item.codigo}?`))return;try{await cambiarEstadoHorario(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(v){error.value=message(v)}}
function clear(){criterio.value='';regimenId.value=null;load(1)}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/recursos">Recursos Humanos</RouterLink> / Horarios</nav><header class="hero"><div class="mark">HT</div><div><small>MIA · RR. HH. · CONTROL DE TIEMPOS</small><h1>Horarios de trabajo</h1><p>Configura las jornadas laborales vinculadas a cada régimen.</p></div><button @click="open()">Nuevo horario</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error&&!modal" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="criterio" placeholder="Buscar por código o descripción"><select v-model="regimenId"><option :value="null">Todos los regímenes</option><option v-for="r in regimenes" :key="r.id" :value="r.id">{{r.codigo}} - {{r.descripcion}}</option></select><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Consultando horarios…</div><div v-else-if="!rows.length" class="empty">No se encontraron horarios.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Código</th><th>Descripción</th><th>Régimen</th><th>1.ª entrada</th><th>1.ª salida</th><th>2.ª entrada</th><th>2.ª salida</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>#{{item.id}}</td><td><b>{{item.codigo}}</b></td><td>{{item.descripcion}}</td><td><b>{{item.regimen?.codigo||'—'}}</b><small v-if="item.regimen">{{item.regimen.descripcion}} · {{item.regimen.horas_dia||0}} h/día</small></td><td><span class="in">{{time(item.entrada_1)}}</span></td><td><span class="out">{{time(item.salida_1)}}</span></td><td>{{time(item.entrada_2)}}</td><td>{{time(item.salida_2)}}</td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'ACTIVO':'INACTIVO'}}</span></td><td class="actions"><button @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}} · {{total}} horarios</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="overlay" @click.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>CONTROL DE TIEMPOS</small><h2>{{editing?'Editar':'Nuevo'}} horario</h2></div><button type="button" @click="modal=false">×</button></header><p v-if="error" class="flash error">{{error}}</p><div class="grid"><label>Régimen *<select v-model="form.regimen_id"><option :value="0">Seleccione</option><option v-for="r in regimenes" :key="r.id" :value="r.id">{{r.codigo}} - {{r.descripcion}}</option></select></label><label>Código *<input v-model="form.codigo" maxlength="20" placeholder="ADM-01"></label><label class="wide">Descripción *<input v-model="form.descripcion" maxlength="150"></label></div><h3>Primer bloque laboral</h3><div class="times"><label>1.ª entrada *<input v-model="form.entrada_1" type="time"></label><label>1.ª salida *<input v-model="form.salida_1" type="time"></label></div><h3>Segundo bloque <small>(opcional)</small></h3><div class="times"><label>2.ª entrada<input v-model="form.entrada_2" type="time"></label><label>2.ª salida<input v-model="form.salida_2" type="time"></label><aside><b>{{duration}}</b><span>Horas laborales calculadas</span></aside></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar horario'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#2697ad;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.2rem}.hero p{margin:0;color:#7e8a90;font-size:.58rem}button{padding:9px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.flash{padding:10px}.success{color:#237453;background:#e7f7ef}.error{color:#a64046;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1fr 1fr auto auto;gap:7px;background:#fff}input,select{padding:9px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.5rem}.soft{color:#64727a;background:#edf1f3}.card{margin-top:12px;background:#fff}.empty{padding:45px;text-align:center}.scroll{overflow:auto}table{width:100%;min-width:1050px;border-collapse:collapse;font-size:.48rem}th,td{padding:8px;border:1px solid #e1e7ea;text-align:left}thead{color:#fff;background:#354a55}td small{display:block;margin-top:3px;color:#8b969b}.in,.out,.active,.inactive{padding:4px 6px;border-radius:9px}.in,.active{color:#247655;background:#e5f5ed}.out,.inactive{color:#a13d45;background:#fdebed}.actions{display:flex;gap:5px}.actions .disable{background:#c58b30}.actions .enable{background:#348261}.card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.5rem}.overlay{position:fixed;inset:0;z-index:50;padding:20px;display:grid;place-items:center;background:#0008}.modal{width:min(760px,96vw);max-height:92vh;overflow:auto;border-radius:11px;background:#fff}.modal>header,.modal>footer{padding:15px;display:flex;align-items:center;justify-content:space-between}.modal h2{margin:2px 0;font-size:1.05rem}.modal>header button{color:#64727a;background:#edf1f3;font-size:1rem}.grid,.times{padding:12px 15px;display:grid;grid-template-columns:1fr 1fr;gap:10px}.grid .wide{grid-column:1/-1}label{display:grid;gap:5px;font-size:.5rem;font-weight:700}.modal h3{margin:8px 15px 0;padding-top:12px;border-top:1px solid #e4e9eb;font-size:.62rem}.modal h3 small{color:#929da2;font-weight:400}.times{grid-template-columns:1fr 1fr 1fr}.times aside{padding:10px;display:grid;place-items:center;border-radius:7px;background:#e8f5f7;font-size:.48rem}.times aside b{font-size:.8rem}.times aside span{color:#718087}@media(max-width:650px){.filters,.grid,.times{grid-template-columns:1fr}.grid .wide{grid-column:auto}.hero p{display:none}}
</style>
